 'exp(-kt)*A^p*exp(-bA)': lambda k,q,p,b: np.exp(-k*t)*A**p*np.exp(-b*A),
 't^q*A^p*exp(-bA)': lambda k,q,p,b: t**q*A**p*np.exp(-b*A),
}
rng=np.random.default_rng(5)
for nm,g in fams.items():
    best=(np.inf,None)
    for trial in range(40):
        p0=np.array([rng.uniform(0.2,1.5),rng.uniform(-2,2),rng.uniform(-2,2),rng.uniform(-1,1),rng.uniform(-1,1)])
        def R(p):
            X=np.column_stack([1/t, np.log(1+p[0]*t)*A**2, g(p[1],p[2],p[3],p[4])])
            c=np.linalg.lstsq(X,y,rcond=None)[0]
            r=X@c-y
